async function fixture(t,width=1280,empty=false,startClinical=true){const f=base(t);f.c.structuredClone=structuredClone;f.sqlite.exec("ALTER TABLE care_patients ADD COLUMN species TEXT DEFAULT 'dog'");f.sqlite.exec(fs.readFileSync(path.join(workerRoot,'migrations/20261026_clinical_workspace.sql'),'utf8'));f.sqlite.exec(fs.readFileSync(path.join(workerRoot,'migrations/20261027_clinical_rooms.sql'),'utf8'));f.sqlite.exec(fs.readFileSync(path.join(workerRoot,'migrations/20261027_ward_workflow.sql'),'utf8'));const api=(p,m='GET',b)=>f.extras('/clinical'+p,m,b);const c=empty?null:await api('/cases','POST',{requestKey:'browser-clinical-case-001',patientId:'p',kind:'admission',species:'dog',weight:5,title:'합성 입원',location:'A1',note:'실제 환자 아님'});const p=await browser.newPage({viewport:{width,height:900}});p.setDefaultTimeout(8000);t.after(()=>p.close());const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.route('**/*',r=>r.request().url().startsWith(origin)?r.continue():r.abort());const requests=[];await p.exposeFunction('testRequest',async(url,options={})=>{requests.push(url);if(url.startsWith('/saas/patient-directory'))return {patients:[{id:'p',name:'합성 환자',species:'dog',guardianName:'합성 보호자'}]};const b=options.body?JSON.parse(options.body):undefined,m=options.method||'GET';if(url==='/saas/practice/reference-safety-summary'&&f.summaryHandler)return f.summaryHandler(b);if(url.startsWith('/saas/practice/references')&&f.referencesHandler)return f.referencesHandler(url.replace('/saas/practice',''));if(url.startsWith('/saas/practice/references'))return f.referenceReady?f.extras(url.replace('/saas/practice',''),m,b):{libraries:[],canManage:true};if(url.startsWith('/saas/practice/clinical')&&f.clinicalHandler)return f.clinicalHandler(url.replace('/saas/practice',''),m,b);if(url.startsWith('/saas/practice/clinical'))return f.extras(url.replace('/saas/practice',''),m,b);if(url.startsWith('/saas/practice/rx/patients/'))return {checks:{body:checks},drafts:[]};if(url==='/saas/practice/strengths'&&f.saveStrengths){const r=await f.extras('/strengths',m,b);f.products=(await f.extras('/presets?strengths=1&formulary=1')).items;return r;}if(url.includes('/presets'))return {items:f.products||[],canManage:true};if(url.startsWith('/saas/practice/patient/'))return {patient:{weight:5,weightDate:'2026-10-26'}};if(url.startsWith('/saas/training'))return {courses:[],assignments:[],actor:{capabilities:{edit:true,review:true,manage:true}}};return {ok:true,runs:[],templates:[],members:[],manager:true,userId:'owner',items:[]};});await p.clock.install();await p.goto(origin+'/index.html');await p.evaluate(empty=>{saasMode='auth';saasSessionMeta={id:'clinical-test'};saasMe={role:'owner',clinic:{id:'a',name:'합성 병원'},user:{id:'owner'}};saasRequest=window.testRequest;window.crmMaterialContext=()=>empty?null:({patientId:'p',patient:{id:'p',name:'합성 환자',species:'dog'},guardian:{name:'합성 보호자'}});showApp();go('practice');},empty);if(!startClinical)return {f,p,api,errors,requests};await p.getByRole('button',{name:'입원·처치 보드',exact:true}).click();await p.locator('[data-cl-action=new]').first().waitFor();if(!empty){await p.locator('[data-cl-case]').first().click();await p.locator('[data-cl-action=order]').waitFor();}else await p.waitForFunction(()=>document.querySelector('[data-cl-action=refresh]')?.disabled===false);return {f,p,api,id:c?.id,errors,requests};}
